import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
}

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() + days);
  return base;
};

const presets = [
  { key: 'today', label: 'Сегодня', offset: 0 },
  { key: 'yesterday', label: 'Вчера', offset: -1 },
  { key: 'weekAgo', label: 'Неделя назад', offset: -7 },
];

export default function ReportDatePicker({ defaultValue = null, onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(defaultValue);

  const apply = (next: Date | null) => {
    setDate(next);
    onChange?.(next);
  };

  const isSameDay = (a: Date | null, b: Date) =>
    a !== null && startOfDay(a).getTime() === b.getTime();

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.offset);
          return (
            <JxChip
              key={preset.key}
              active={isSameDay(date, presetDate)}
              onClick={() => apply(presetDate)}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={apply} />
    </div>
  );
}

